DROP TABLE IF EXISTS `staff_roles`;
CREATE TABLE `staff_roles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `staff_roles_code_unique` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `store_product_inventories`;
CREATE TABLE `store_product_inventories` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `store_id` bigint(20) unsigned NOT NULL,
  `product_id` bigint(20) unsigned NOT NULL,
  `custom_price` decimal(10,2) DEFAULT NULL,
  `custom_mrp` decimal(10,2) DEFAULT NULL,
  `custom_stock` int(11) NOT NULL DEFAULT 0,
  `custom_reserved_stock` int(11) NOT NULL DEFAULT 0,
  `custom_low_stock_threshold` int(11) NOT NULL DEFAULT 10,
  `custom_critical_stock_threshold` int(11) NOT NULL DEFAULT 5,
  `is_available` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `store_product_inventories_store_id_product_id_unique` (`store_id`,`product_id`),
  KEY `store_product_inventories_product_id_foreign` (`product_id`),
  CONSTRAINT `store_product_inventories_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `store_product_inventories_store_id_foreign` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `stores`;
CREATE TABLE `stores` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `code` varchar(255) NOT NULL,
  `address` varchar(255) NOT NULL,
  `latitude` decimal(10,7) NOT NULL DEFAULT 23.4013000,
  `longitude` decimal(10,7) NOT NULL DEFAULT 88.5010000,
  `delivery_radius_km` decimal(5,2) NOT NULL DEFAULT 5.00,
  `city` varchar(255) NOT NULL DEFAULT 'Krishnanagar',
  `pincode` varchar(255) NOT NULL DEFAULT '741101',
  `banner_title` varchar(255) DEFAULT 'Mega Diwali Sale',
  `banner_subtitle` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `status` enum('Active','Inactive','Temporarily Closed','Maintenance') NOT NULL DEFAULT 'Active',
  `opening_time` time NOT NULL DEFAULT '06:00:00',
  `closing_time` time NOT NULL DEFAULT '23:00:00',
  `operating_hours` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`operating_hours`)),
  `holidays` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`holidays`)),
  `temporary_closure_reason` varchar(255) DEFAULT NULL,
  `vacation_mode` tinyint(1) NOT NULL DEFAULT 0,
  `min_order_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `delivery_fee` decimal(10,2) NOT NULL DEFAULT 15.00,
  `free_delivery_threshold` decimal(10,2) NOT NULL DEFAULT 299.00,
  `estimated_delivery_time_mins` int(11) NOT NULL DEFAULT 15,
  `prep_time_mins` int(11) NOT NULL DEFAULT 5,
  `store_phone` varchar(255) DEFAULT NULL,
  `store_email` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `banner_color` varchar(255) DEFAULT '#0c831f',
  `search_hint` varchar(255) DEFAULT 'milk, atta, chips, diwali lights',
  `promo_grid_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`promo_grid_json`)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `stores_code_unique` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

